```python
from collections import deque

A_TURN_LEFT = 0
A_TURN_RIGHT = 1
A_FORWARD = 2
A_PICKUP = 3
A_DROP = 4
A_TOGGLE = 5
A_DONE = 6

# direction vectors: 0 east, 1 south, 2 west, 3 north
DIR_VECS = [(1, 0), (0, 1), (-1, 0), (0, -1)]

def controller(state) -> int:
    """
    Lightweight staged controller optimized to avoid copying or serializing the grid.
    It performs small BFS searches over positions only (no grid copies) and decides
    one primitive action per call.
    """
    width = state['width']
    height = state['height']
    grid = state['grid']
    pos = tuple(state['agent_pos'])
    dir = int(state['agent_dir'])
    carrying = state['carrying']  # None or dict
    if carrying is not None:
        carrying_type = carrying.get('type')
        carrying_color = carrying.get('color')
    else:
        carrying_type = None
        carrying_color = None

    def in_bounds(x, y):
        return 0 <= x < width and 0 <= y < height

    def cell_at(x, y):
        if not in_bounds(x, y):
            return {'type': 'wall'}
        return grid[y][x]

    def front_coord(p, d):
        dx, dy = DIR_VECS[d]
        return (p[0] + dx, p[1] + dy)

    # Decide if the agent can stand on a cell (for path node).
    # Allow standing on floor (None), goal, open door. Also allow standing on a closed door
    # if it is not locked (we can toggle it) or if locked but we carry the matching key.
    # We treat key/ball/box as non-standable (they block movement).
    def standable(cell):
        if cell is None:
            return True
        t = cell.get('type')
        if t == 'goal':
            return True
        if t == 'door':
            if cell.get('is_open'):
                return True
            if cell.get('is_locked'):
                # we can stand on the door cell only if we can unlock it (i.e. carry matching key)
                return (carrying_type == 'key' and carrying_color == cell.get('color'))
            # closed but unlocked door: we can open it and stand in it
            return True
        return False  # key, ball, box, wall, lava etc block standing

    # For pathfinding we allow stepping into door cells even if closed as long as we can open/unlock it.
    # This mirrors standable().
    def walkable(cell):
        return standable(cell)

    # BFS pathfinder on positions (ignores agent_dir). Returns list of positions (including start and goal)
    # or None if unreachable.
    def bfs_path(start, goals):
        # goals: set of (x,y) positions that we want to reach (standing positions)
        if start in goals:
            return [start]
        q = deque()
        q.append(start)
        prev = {start: None}
        while q:
            cur = q.popleft()
            cx, cy = cur
            for dx, dy in DIR_VECS:
                nx, ny = cx + dx, cy + dy
                if not in_bounds(nx, ny):
                    continue
                if (nx, ny) in prev:
                    continue
                c = cell_at(nx, ny)
                if not walkable(c):
                    continue
                prev[(nx, ny)] = cur
                if (nx, ny) in goals:
                    # reconstruct path
                    path = [(nx, ny)]
                    p = cur
                    while p is not None:
                        path.append(p)
                        p = prev[p]
                    path.reverse()
                    return path
                q.append((nx, ny))
        return None

    # Find any standing position adjacent to target_pos that allows interacting with target (i.e., standing
    # cell must be walkable). For keys and balls we need to stand adjacent; for doors we need to stand adjacent.
    def adjacent_stand_positions(target_pos):
        tx, ty = target_pos
        res = set()
        for d, (dx, dy) in enumerate(DIR_VECS):
            sx, sy = tx - dx, ty - dy  # standing position such that facing direction d will look at target
            if not in_bounds(sx, sy):
                continue
            c = cell_at(sx, sy)
            if standable(c):
                res.add((sx, sy))
        return res

    # Find nearest key cell (position). Return its coords or None.
    def find_any_key():
        for y in range(height):
            for x in range(width):
                c = cell_at(x, y)
                if c is not None and c.get('type') == 'key':
                    return (x, y)
        return None

    # Find the ball cell
    def find_ball():
        for y in range(height):
            for x in range(width):
                c = cell_at(x, y)
                if c is not None and c.get('type') == 'ball':
                    return (x, y)
        return None

    # Find a door cell matching a color and preferably locked
    def find_matching_door(color):
        locked_doors = []
        other_doors = []
        for y in range(height):
            for x in range(width):
                c = cell_at(x, y)
                if c is not None and c.get('type') == 'door' and c.get('color') == color:
                    if c.get('is_locked'):
                        locked_doors.append((x, y))
                    else:
                        other_doors.append((x, y))
        if locked_doors:
            return locked_doors[0]
        if other_doors:
            return other_doors[0]
        return None

    # Find a reachable position where forward cell is empty (so we can drop).
    # Returns (path, target_front_coord) where path leads to a standing cell and target_front_coord is the cell ahead to drop onto.
    def find_pos_with_empty_front():
        # BFS over standing positions. For each visited pos check if any direction leads to empty floor in front.
        start = pos
        q = deque()
        q.append(start)
        prev = {start: None}
        while q:
            cur = q.popleft()
            cx, cy = cur
            # check all directions for an empty front cell
            for d, (dx, dy) in enumerate(DIR_VECS):
                fx, fy = cx + dx, cy + dy
                if not in_bounds(fx, fy):
                    continue
                front = cell_at(fx, fy)
                # we want an empty floor (None) to drop into; do not choose the ball cell
                if front is None:
                    # found a place to drop, reconstruct path to cur
                    path = [cur]
                    p = prev[cur]
                    while p is not None:
                        path.append(p)
                        p = prev[p]
                    path.reverse()
                    return path, (fx, fy), d  # also return direction to face to drop
            # expand neighbors
            for dx, dy in DIR_VECS:
                nx, ny = cx + dx, cy + dy
                if not in_bounds(nx, ny):
                    continue
                if (nx, ny) in prev:
                    continue
                c = cell_at(nx, ny)
                if not walkable(c):
                    continue
                prev[(nx, ny)] = cur
                q.append((nx, ny))
        return None, None, None

    # Quick immediate checks for front cell interactions:
    fx, fy = front_coord(pos, dir)
    front = cell_at(fx, fy)

    # If already carrying ball -> done
    if carrying_type == 'ball':
        return A_DONE

    # If front has a key and we can pick it up (not carrying) -> pickup
    if front is not None and front.get('type') == 'key' and carrying is None:
        return A_PICKUP

    # If front has ball:
    if front is not None and front.get('type') == 'ball':
        # If not carrying anything -> pickup
        if carrying is None:
            return A_PICKUP
        # If carrying a key -> must drop key somewhere before picking ball
        if carrying_type == 'key':
            # find a reachable place to drop
            path, drop_cell, drop_dir = find_pos_with_empty_front()
            if path is None:
                # fallback: rotate to try find spot next steps
                return A_TURN_RIGHT
            # if we are already at the position to drop (path length 1 and facing correct direction), drop
            target_stand = path[-1]
            if pos == target_stand:
                # we must face drop_dir to drop
                if dir != drop_dir:
                    # choose shortest turn
                    diff = (drop_dir - dir) % 4
                    if diff == 1:
                        return A_TURN_RIGHT
                    if diff == 3:
                        return A_TURN_LEFT
                    # diff == 2
                    return A_TURN_RIGHT
                # front should be empty (we checked), so drop now
                return A_DROP
            # else navigate along path to target_stand
            # compute next step
            if len(path) >= 2:
                next_pos = path[1]
                dx = next_pos[0] - pos[0]
                dy = next_pos[1] - pos[1]
                # compute desired dir
                for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
                    if ddx == dx and ddy == dy:
                        desired_dir = d_idx
                        break
                else:
                    desired_dir = dir
                if dir != desired_dir:
                    diff = (desired_dir - dir) % 4
                    if diff == 1:
                        return A_TURN_RIGHT
                    if diff == 3:
                        return A_TURN_LEFT
                    return A_TURN_RIGHT
                # if the next cell is a closed door we should toggle (if possible) before forward
                next_cell = cell_at(next_pos[0], next_pos[1])
                if next_cell is not None and next_cell.get('type') == 'door' and not next_cell.get('is_open'):
                    # if locked and we have matching key -> toggle (this will unlock/open)
                    if next_cell.get('is_locked'):
                        if carrying_type == 'key' and carrying_color == next_cell.get('color'):
                            return A_TOGGLE
                        else:
                            # should not happen because walkable would've prevented it; fallback rotate
                            return A_TURN_RIGHT
                    else:
                        return A_TOGGLE
                return A_FORWARD
            else:
                return A_TURN_RIGHT

    # If front is a door: handle toggling/opening/unlocking/immediate movement
    if front is not None and front.get('type') == 'door':
        if front.get('is_locked'):
            # If we carry matching key -> unlock (toggle)
            if carrying_type == 'key' and carrying_color == front.get('color'):
                return A_TOGGLE
            # otherwise cannot open; we should navigate somewhere else (rotate)
            # (This normally won't happen in valid tasks where the only locked door is unlockable)
            return A_TURN_RIGHT
        else:
            # door not locked: if closed, toggle open; if open, move forward
            if not front.get('is_open'):
                return A_TOGGLE
            # open door: move forward
            return A_FORWARD

    # If carrying a key, target the matching door (locked preferred)
    if carrying_type == 'key':
        door_pos = find_matching_door(carrying_color)
        # If no door of that color found, go straight to ball
        if door_pos is not None:
            # If door is adjacent and we're in position to toggle, handle above; else plan path to stand adjacent to door
            stand_targets = adjacent_stand_positions(door_pos)
            if not stand_targets:
                # nothing to stand on adjacent to door (should not happen) - fallback rotate
                return A_TURN_RIGHT
            path = bfs_path(pos, stand_targets)
            if path is None:
                return A_TURN_RIGHT
            # If at target stand position, face door and toggle if needed; else navigate along path
            target_stand = path[-1]
            if pos == target_stand:
                # face door location
                dx = door_pos[0] - pos[0]
                dy = door_pos[1] - pos[1]
                desired_dir = None
                for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
                    if ddx == dx and ddy == dy:
                        desired_dir = d_idx
                        break
                if desired_dir is None:
                    return A_TURN_RIGHT
                if dir != desired_dir:
                    diff = (desired_dir - dir) % 4
                    if diff == 1:
                        return A_TURN_RIGHT
                    if diff == 3:
                        return A_TURN_LEFT
                    return A_TURN_RIGHT
                # once facing door, toggle (this will unlock if locked and we have key)
                return A_TOGGLE
            # not yet at stand pos: move towards it
            if len(path) >= 2:
                next_pos = path[1]
                dx = next_pos[0] - pos[0]
                dy = next_pos[1] - pos[1]
                desired_dir = None
                for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
                    if ddx == dx and ddy == dy:
                        desired_dir = d_idx
                        break
                if desired_dir is None:
                    return A_TURN_RIGHT
                if dir != desired_dir:
                    diff = (desired_dir - dir) % 4
                    if diff == 1:
                        return A_TURN_RIGHT
                    if diff == 3:
                        return A_TURN_LEFT
                    return A_TURN_RIGHT
                # if next cell is a closed door, toggle before forward
                next_cell = cell_at(next_pos[0], next_pos[1])
                if next_cell is not None and next_cell.get('type') == 'door' and not next_cell.get('is_open'):
                    if next_cell.get('is_locked'):
                        if carrying_type == 'key' and carrying_color == next_cell.get('color'):
                            return A_TOGGLE
                        else:
                            return A_TURN_RIGHT
                    else:
                        return A_TOGGLE
                return A_FORWARD
            return A_TURN_RIGHT

    # If not carrying a key: search for a key and go pick it up.
    key_pos = find_any_key()
    if key_pos is not None and carrying is None:
        # target: stand adjacent to key
        stand_targets = adjacent_stand_positions(key_pos)
        if not stand_targets:
            return A_TURN_RIGHT
        path = bfs_path(pos, stand_targets)
        if path is None:
            return A_TURN_RIGHT
        target_stand = path[-1]
        # If at stand position and facing key, pick it up
        if pos == target_stand:
            dx = key_pos[0] - pos[0]
            dy = key_pos[1] - pos[1]
            desired_dir = None
            for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
                if ddx == dx and ddy == dy:
                    desired_dir = d_idx
                    break
            if desired_dir is None:
                return A_TURN_RIGHT
            if dir != desired_dir:
                diff = (desired_dir - dir) % 4
                if diff == 1:
                    return A_TURN_RIGHT
                if diff == 3:
                    return A_TURN_LEFT
                return A_TURN_RIGHT
            # now face key: pick up
            # Double-check front indeed has a key
            fx2, fy2 = front_coord(pos, dir)
            if in_bounds(fx2, fy2) and cell_at(fx2, fy2) is not None and cell_at(fx2, fy2).get('type') == 'key':
                return A_PICKUP
            # otherwise fallback rotate
            return A_TURN_RIGHT
        # else navigate along path
        if len(path) >= 2:
            next_pos = path[1]
            dx = next_pos[0] - pos[0]
            dy = next_pos[1] - pos[1]
            desired_dir = None
            for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
                if ddx == dx and ddy == dy:
                    desired_dir = d_idx
                    break
            if desired_dir is None:
                return A_TURN_RIGHT
            if dir != desired_dir:
                diff = (desired_dir - dir) % 4
                if diff == 1:
                    return A_TURN_RIGHT
                if diff == 3:
                    return A_TURN_LEFT
                return A_TURN_RIGHT
            next_cell = cell_at(next_pos[0], next_pos[1])
            if next_cell is not None and next_cell.get('type') == 'door' and not next_cell.get('is_open'):
                if next_cell.get('is_locked'):
                    # cannot pass locked door to reach key (should not happen), rotate
                    return A_TURN_RIGHT
                return A_TOGGLE
            return A_FORWARD
        return A_TURN_RIGHT

    # If we reach here, try to go to the ball (either we have no key and no key exists, or we've unlocked door and are inside)
    ball_pos = find_ball()
    if ball_pos is None:
        return A_TURN_RIGHT

    # If not carrying anything, just go pick up the ball (stand adjacent and pick)
    # If carrying key but we didn't handle drop earlier, still aim to find place to drop first
    if carrying_type == 'key':
        # find position to drop first (empty front). We'll move there.
        path, drop_cell, drop_dir = find_pos_with_empty_front()
        if path is None:
            return A_TURN_RIGHT
        target_stand = path[-1]
        if pos == target_stand:
            # face drop_dir and drop
            if dir != drop_dir:
                diff = (drop_dir - dir) % 4
                if diff == 1:
                    return A_TURN_RIGHT
                if diff == 3:
                    return A_TURN_LEFT
                return A_TURN_RIGHT
            return A_DROP
        # else move along path
        if len(path) >= 2:
            next_pos = path[1]
            dx = next_pos[0] - pos[0]
            dy = next_pos[1] - pos[1]
            desired_dir = None
            for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
                if ddx == dx and ddy == dy:
                    desired_dir = d_idx
                    break
            if desired_dir is None:
                return A_TURN_RIGHT
            if dir != desired_dir:
                diff = (desired_dir - dir) % 4
                if diff == 1:
                    return A_TURN_RIGHT
                if diff == 3:
                    return A_TURN_LEFT
                return A_TURN_RIGHT
            next_cell = cell_at(next_pos[0], next_pos[1])
            if next_cell is not None and next_cell.get('type') == 'door' and not next_cell.get('is_open'):
                if next_cell.get('is_locked'):
                    if carrying_type == 'key' and carrying_color == next_cell.get('color'):
                        return A_TOGGLE
                    return A_TURN_RIGHT
                return A_TOGGLE
            return A_FORWARD
        return A_TURN_RIGHT

    # Not carrying key and no key found? Just go adjacent to ball and pick
    stand_targets = adjacent_stand_positions(ball_pos)
    if not stand_targets:
        return A_TURN_RIGHT
    path = bfs_path(pos, stand_targets)
    if path is None:
        return A_TURN_RIGHT
    target_stand = path[-1]
    if pos == target_stand:
        # face the ball and pick
        dx = ball_pos[0] - pos[0]
        dy = ball_pos[1] - pos[1]
        desired_dir = None
        for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
            if ddx == dx and ddy == dy:
                desired_dir = d_idx
                break
        if desired_dir is None:
            return A_TURN_RIGHT
        if dir != desired_dir:
            diff = (desired_dir - dir) % 4
            if diff == 1:
                return A_TURN_RIGHT
            if diff == 3:
                return A_TURN_LEFT
            return A_TURN_RIGHT
        # if front is ball pick it
        fx2, fy2 = front_coord(pos, dir)
        if in_bounds(fx2, fy2) and cell_at(fx2, fy2) is not None and cell_at(fx2, fy2).get('type') == 'ball':
            return A_PICKUP
        return A_TURN_RIGHT
    # else move along path
    if len(path) >= 2:
        next_pos = path[1]
        dx = next_pos[0] - pos[0]
        dy = next_pos[1] - pos[1]
        desired_dir = None
        for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
            if ddx == dx and ddy == dy:
                desired_dir = d_idx
                break
        if desired_dir is None:
            return A_TURN_RIGHT
        if dir != desired_dir:
            diff = (desired_dir - dir) % 4
            if diff == 1:
                return A_TURN_RIGHT
            if diff == 3:
                return A_TURN_LEFT
            return A_TURN_RIGHT
        next_cell = cell_at(next_pos[0], next_pos[1])
        if next_cell is not None and next_cell.get('type') == 'door' and not next_cell.get('is_open'):
            if next_cell.get('is_locked'):
                # can't pass locked door
                return A_TURN_RIGHT
            return A_TOGGLE
        return A_FORWARD

    return A_TURN_RIGHT
