```python
from collections import deque

A_TURN_LEFT = 0
A_TURN_RIGHT = 1
A_FORWARD = 2
A_PICKUP = 3
A_DROP = 4
A_TOGGLE = 5
A_DONE = 6

# direction vectors: 0 east, 1 south, 2 west, 3 north
DIR_VECS = [(1, 0), (0, 1), (-1, 0), (0, -1)]


def controller(state) -> int:
    """
    Fast staged controller for the key-door-ball corridor task.
    Strategy (recomputed each call, no heavy copies):
      - If carrying the ball -> DONE.
      - If front has ball and not carrying key -> PICKUP.
      - If carrying key -> go to matching door, unlock (TOGGLE) while facing it, move through, then
        find nearest reachable place with an empty front cell and DROP the key, then go to the ball and PICKUP.
      - If not carrying key -> go to the key, PICKUP it (open any unlocked doors along the way).
    Pathfinding: BFS over positions only. Doors are considered traversable if:
      - door is open, or
      - door is closed but unlocked (we can toggle it), or
      - door is locked but we carry the matching key (we can unlock).
    Keys/balls/boxes/walls/lava block stepping into their cell (we stand on floor/goal/open-door cells).
    The controller chooses short local actions to follow computed paths (turn, toggle when in front of closed door,
    forward, pickup/drop).
    """
    width = state['width']
    height = state['height']
    grid = state['grid']
    pos = tuple(state['agent_pos'])
    dir = int(state['agent_dir'])
    carrying = state['carrying']
    carrying_type = carrying.get('type') if carrying is not None else None
    carrying_color = carrying.get('color') if carrying is not None else None

    def in_bounds(x, y):
        return 0 <= x < width and 0 <= y < height

    def cell_at(x, y):
        if not in_bounds(x, y):
            # treat out of bounds as wall-like
            return {'type': 'wall'}
        return grid[y][x]

    def front_coord(p, d):
        dx, dy = DIR_VECS[d]
        return (p[0] + dx, p[1] + dy)

    # Determine if we can stand on this cell (i.e., forward can move into it)
    def standable(cell):
        if cell is None:
            return True
        t = cell.get('type')
        if t == 'goal':
            return True
        if t == 'door':
            # open door -> standable
            if cell.get('is_open'):
                return True
            # closed door but unlocked -> we can toggle and then enter
            if not cell.get('is_locked'):
                return True
            # locked door -> only standable if we hold matching key (we can unlock it)
            if carrying_type == 'key' and carrying_color == cell.get('color'):
                return True
            return False
        # everything else (key/ball/box/wall/lava) blocks
        return False

    # For pathfinding we consider the same rule as standable
    def walkable(cell):
        return standable(cell)

    # BFS to any of goal positions; goals is a set of (x,y) positions we want to reach (standing positions)
    def bfs_to_targets(start, goals):
        if start in goals:
            return [start]
        q = deque()
        q.append(start)
        prev = {start: None}
        while q:
            cur = q.popleft()
            cx, cy = cur
            for dx, dy in DIR_VECS:
                nx, ny = cx + dx, cy + dy
                if not in_bounds(nx, ny):
                    continue
                if (nx, ny) in prev:
                    continue
                c = cell_at(nx, ny)
                if not walkable(c):
                    continue
                prev[(nx, ny)] = cur
                if (nx, ny) in goals:
                    # reconstruct path
                    path = [(nx, ny)]
                    p = cur
                    while p is not None:
                        path.append(p)
                        p = prev[p]
                    path.reverse()
                    return path
                q.append((nx, ny))
        return None

    # Return set of standing positions adjacent to target_pos (where agent can stand to interact with target)
    def adjacent_stands(target_pos):
        tx, ty = target_pos
        res = set()
        for dx, dy in DIR_VECS:
            sx, sy = tx - dx, ty - dy  # standing so that facing direction dx,dy points at target
            if not in_bounds(sx, sy):
                continue
            if walkable(cell_at(sx, sy)):
                res.add((sx, sy))
        return res

    # Find positions of objects
    def find_any_key():
        for y in range(height):
            row = grid[y]
            for x in range(width):
                c = row[x]
                if c is not None and c.get('type') == 'key':
                    return (x, y)
        return None

    def find_ball():
        for y in range(height):
            row = grid[y]
            for x in range(width):
                c = row[x]
                if c is not None and c.get('type') == 'ball':
                    return (x, y)
        return None

    def find_matching_door(color):
        # prefer locked doors first
        locked = None
        unlocked = None
        for y in range(height):
            row = grid[y]
            for x in range(width):
                c = row[x]
                if c is not None and c.get('type') == 'door' and c.get('color') == color:
                    if c.get('is_locked'):
                        return (x, y)
                    if unlocked is None:
                        unlocked = (x, y)
        return unlocked

    # Find a reachable standing position that has an empty front cell to drop into.
    # Return (path_to_stand, front_cell_coord, front_direction)
    def find_drop_spot():
        q = deque()
        q.append(pos)
        prev = {pos: None}
        while q:
            cur = q.popleft()
            cx, cy = cur
            for d_idx, (dx, dy) in enumerate(DIR_VECS):
                fx, fy = cx + dx, cy + dy
                if not in_bounds(fx, fy):
                    continue
                # front cell must be empty floor (None) and not the ball
                frontc = cell_at(fx, fy)
                if frontc is None:
                    # reconstruct path to cur
                    path = [cur]
                    p = prev[cur]
                    while p is not None:
                        path.append(p)
                        p = prev[p]
                    path.reverse()
                    return path, (fx, fy), d_idx
            # expand neighbors
            for dx, dy in DIR_VECS:
                nx, ny = cx + dx, cy + dy
                if not in_bounds(nx, ny):
                    continue
                if (nx, ny) in prev:
                    continue
                if not walkable(cell_at(nx, ny)):
                    continue
                prev[(nx, ny)] = cur
                q.append((nx, ny))
        return None, None, None

    # Simple helper: given desired direction, produce a single turn action to approach it
    def turn_towards(cur_dir, desired_dir):
        diff = (desired_dir - cur_dir) % 4
        if diff == 0:
            return None
        if diff == 1:
            return A_TURN_RIGHT
        if diff == 3:
            return A_TURN_LEFT
        # diff == 2: arbitrary choose turn right (two rights will be needed subsequently)
        return A_TURN_RIGHT

    # Low-level step executor: given path (list of positions from current pos to goal stand), output one primitive action
    def step_along_path(path):
        # path[0] should be current pos
        if len(path) <= 1:
            return None
        next_pos = path[1]
        dx = next_pos[0] - pos[0]
        dy = next_pos[1] - pos[1]
        desired_dir = None
        for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
            if ddx == dx and ddy == dy:
                desired_dir = d_idx
                break
        if desired_dir is None:
            return A_TURN_RIGHT
        if dir != desired_dir:
            a = turn_towards(dir, desired_dir)
            return a if a is not None else A_TURN_RIGHT
        # facing desired direction: check front cell
        fx, fy = front_coord(pos, dir)
        front = cell_at(fx, fy)
        if front is not None and front.get('type') == 'door' and not front.get('is_open'):
            # if locked and we carry matching key -> toggle will unlock and open
            if front.get('is_locked'):
                if carrying_type == 'key' and carrying_color == front.get('color'):
                    return A_TOGGLE
                # cannot pass locked door
                return A_TURN_RIGHT
            else:
                # closed but unlocked: open it
                return A_TOGGLE
        # otherwise forward
        return A_FORWARD

    # Start of staged decisions:

    # If already carrying ball -> done
    if carrying_type == 'ball':
        return A_DONE

    # Immediate front interactions:
    fx, fy = front_coord(pos, dir)
    frontcell = cell_at(fx, fy)

    # If front has ball and we can pick it (not carrying anything) -> pick
    if frontcell is not None and frontcell.get('type') == 'ball' and carrying is None:
        return A_PICKUP

    # If carrying a key and front is a closed locked door of matching color and facing it -> toggle (unlock)
    if carrying_type == 'key' and frontcell is not None and frontcell.get('type') == 'door' and frontcell.get('is_locked') and carrying_color == frontcell.get('color'):
        return A_TOGGLE

    # If front is a closed but unlocked door -> toggle to open
    if frontcell is not None and frontcell.get('type') == 'door' and not frontcell.get('is_open') and not frontcell.get('is_locked'):
        return A_TOGGLE

    # If carrying key: first go to its matching door, unlock and pass, then drop key somewhere, then go to ball
    if carrying_type == 'key':
        # If there is a reachable drop spot right now in front (we're at stand pos and front empty), prefer drop if ball is not in front
        # But we must drop before picking ball; check if front is empty and we intend to pick ball next (i.e., ball adjacent and facing)
        # If front is empty and not a ball, drop now when we are at a location where picking next is possible.
        # Find nearest drop spot
        drop_path, drop_front_cell, drop_dir = find_drop_spot()
        # If at drop stand and facing the drop front, drop
        if drop_path is not None and len(drop_path) >= 1:
            target_stand = drop_path[-1]
            if pos == target_stand:
                # face drop_dir
                if dir != drop_dir:
                    turn = turn_towards(dir, drop_dir)
                    return turn if turn is not None else A_TURN_RIGHT
                # ensure front is still empty
                if in_bounds(drop_front_cell[0], drop_front_cell[1]) and cell_at(drop_front_cell[0], drop_front_cell[1]) is None:
                    return A_DROP
            # Not at drop stand: but first we must go to door and unlock if we haven't passed it yet.
        # Before dropping, ensure we've unlocked and passed the matching door.
        door_pos = find_matching_door(carrying_color)
        if door_pos is not None:
            # Determine if we are already on the other side of the door (i.e., ball is nearer or drop spot found inside)
            # We'll aim to stand adjacent to the door and toggle if necessary, otherwise path to door-adjacent
            stands = adjacent_stands(door_pos)
            if stands:
                path = bfs_to_targets(pos, stands)
                if path is None:
                    # cannot reach stands (maybe on other side already) -> proceed to drop spot or ball
                    pass
                else:
                    # If at stand position already, face door and toggle (unlock) if needed, or step through
                    target_stand = path[-1]
                    if pos == target_stand:
                        # face the door
                        dx = door_pos[0] - pos[0]
                        dy = door_pos[1] - pos[1]
                        desired_dir = None
                        for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
                            if ddx == dx and ddy == dy:
                                desired_dir = d_idx
                                break
                        if desired_dir is None:
                            return A_TURN_RIGHT
                        if dir != desired_dir:
                            turn = turn_towards(dir, desired_dir)
                            return turn if turn is not None else A_TURN_RIGHT
                        # facing door: if it's locked and matches, toggle; if closed and unlocked, toggle; if open, move forward
                        dd = cell_at(door_pos[0], door_pos[1])
                        if dd is not None and dd.get('type') == 'door':
                            if dd.get('is_locked'):
                                if carrying_type == 'key' and carrying_color == dd.get('color'):
                                    return A_TOGGLE
                                else:
                                    return A_TURN_RIGHT
                            if not dd.get('is_open'):
                                return A_TOGGLE
                            # open -> move through
                            return A_FORWARD
                    else:
                        # not yet at stand: move along path one step
                        act = step_along_path(path)
                        return act if act is not None else A_TURN_RIGHT
        # If we couldn't find or handle door for some reason, but we have a valid drop_path, move toward drop
        if drop_path is not None:
            if pos == drop_path[-1]:
                # facing drop_dir handled above; else handled there
                pass
            else:
                act = step_along_path(drop_path)
                return act if act is not None else A_TURN_RIGHT
        # As a fallback, rotate to try find a spot next call
        return A_TURN_RIGHT

    # If not carrying key: go to key and pick it up
    if carrying is None:
        key_pos = find_any_key()
        if key_pos is not None:
            stands = adjacent_stands(key_pos)
            if stands:
                path = bfs_to_targets(pos, stands)
                if path is not None:
                    target_stand = path[-1]
                    if pos == target_stand:
                        # face the key and pick
                        dx = key_pos[0] - pos[0]
                        dy = key_pos[1] - pos[1]
                        desired_dir = None
                        for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
                            if ddx == dx and ddy == dy:
                                desired_dir = d_idx
                                break
                        if desired_dir is None:
                            return A_TURN_RIGHT
                        if dir != desired_dir:
                            turn = turn_towards(dir, desired_dir)
                            return turn if turn is not None else A_TURN_RIGHT
                        # front should be key, pick
                        fx2, fy2 = front_coord(pos, dir)
                        if in_bounds(fx2, fy2):
                            c = cell_at(fx2, fy2)
                            if c is not None and c.get('type') == 'key':
                                return A_PICKUP
                        return A_TURN_RIGHT
                    else:
                        act = step_along_path(path)
                        return act if act is not None else A_TURN_RIGHT
            # no standable adjacent to key -> give up and rotate
            return A_TURN_RIGHT

    # If we reach here and not carrying key (maybe picked and dropped earlier), go to ball and pick it
    ball_pos = find_ball()
    if ball_pos is not None:
        stands = adjacent_stands(ball_pos)
        if stands:
            path = bfs_to_targets(pos, stands)
            if path is not None:
                target_stand = path[-1]
                if pos == target_stand:
                    # face ball
                    dx = ball_pos[0] - pos[0]
                    dy = ball_pos[1] - pos[1]
                    desired_dir = None
                    for d_idx, (ddx, ddy) in enumerate(DIR_VECS):
                        if ddx == dx and ddy == dy:
                            desired_dir = d_idx
                            break
                    if desired_dir is None:
                        return A_TURN_RIGHT
                    if dir != desired_dir:
                        turn = turn_towards(dir, desired_dir)
                        return turn if turn is not None else A_TURN_RIGHT
                    # if front is ball and not carrying -> pick
                    fx2, fy2 = front_coord(pos, dir)
                    if in_bounds(fx2, fy2):
                        c = cell_at(fx2, fy2)
                        if c is not None and c.get('type') == 'ball' and carrying is None:
                            return A_PICKUP
                    return A_TURN_RIGHT
                else:
                    act = step_along_path(path)
                    return act if act is not None else A_TURN_RIGHT
        return A_TURN_RIGHT

    # Fallback: rotate to explore
    return A_TURN_RIGHT
